function store(){try{localStorage.setItem(KEY,JSON.stringify({version:DATA.version,order,index,logs,session,subject,started}));$('storage').textContent='已保存到本浏览器；结束后请导出CSV。'}catch(e){$('storage').textContent='本浏览器不能自动保存，请及时导出CSV。'}}
try{saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.version===DATA.version&&saved.logs.length<24&&saved.logs.length>0)$('resume').hidden=false}catch(e){}
function show(id){['intro','quiz','break','done'].forEach(x=>$(x).hidden=x!==id)}
function stopAudio(){if(player){player.onended=null;player.onerror=null;player.pause();player=null}playing=false}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
$('random').onclick=()=>{order=[...shuffle(DATA.questions.slice(0,12).map(x=>({...x}))),...shuffle(DATA.questions.slice(12).map(x=>({...x})))];$('sampleNote').textContent='已重新排序；每单元仍有12种题型。导出记录按实际顺序保存。'};
$('sample').onclick=async()=>{if(playing)return;let targets=[[850,1105],[1105,850]],p=targets[sampleIndex%2],q=DATA.questions.find(x=>x.first_ms===p[0]&&x.second_ms===p[1]);sampleIndex++;playing=true;$('sample').disabled=true;$('start').disabled=true;$('sampleNote').textContent='请听完，再看讲解。';player=new Audio(DATA.audio[q.id]);let finish=()=>{playing=false;$('sample').disabled=false;$('start').disabled=false};player.onended=()=>{finish();$('sampleNote').textContent=`本题第${q.answer}段间隔更长。比较的是相邻声音之间的等待时间。可再次点击试听另一个例题。`};player.onerror=()=>{finish();$('sampleNote').textContent='播放失败，请更换支持WAV的浏览器后再试。'};try{await player.play()}catch(e){finish();$('sampleNote').textContent='无法播放，请检查浏览器声音权限。'}};
function draw(){show('quiz');ready=false;answered=false;attempts=0;interruptions=0;$('position').textContent=`第 ${index+1} / 24 题 · 第 ${Math.floor(index/12)+1} 单元`;$('bar').value=index;$('status').textContent='请播放本题，听完后再回答。';$('result').textContent='';$('play').disabled=false;$('interrupt').disabled=true;$('a1').disabled=$('a2').disabled=true;$('next').hidden=true}
$('start').onclick=()=>{stopAudio();subject=$('pid').value.trim();session='AIDT-'+Date.now();started=new Date().toISOString();index=0;logs=[];store();draw()};
$('resume').onclick=()=>{({order,index,logs,session,subject,started}=saved);index=logs.length;if(index===12){show('break')}else{draw()}};
$('play').onclick=async()=>{if(playing||answered||ready)return;attempts++;playing=true;$('play').disabled=true;$('interrupt').disabled=false;$('status').textContent='正在播放，请安静聆听。';player=new Audio(DATA.audio[order[index].id]);const currentAudio=player;player.onended=()=>{playing=false;ready=true;$('interrupt').disabled=true;$('a1').disabled=$('a2').disabled=false;$('status').textContent='哪一段间隔更长？请患者先说答案，再由家属点击。'};player.onerror=()=>abort('音频播放失败，请检查设备后重播。');try{await currentAudio.play()}catch(e){if(player===currentAudio&&playing)abort('浏览器未能播放，请检查声音权限后重试。')}};
function abort(msg){stopAudio();interruptions++;ready=false;$('play').disabled=false;$('interrupt').disabled=true;$('a1').disabled=$('a2').disabled=true;$('status').textContent=msg}
$('interrupt').onclick=()=>abort('已标记播放中断。准备好后完整重播本题。');
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing&& !$('quiz').hidden)abort('页面切换中断了播放，请回到页面后重播。')});
function answer(value){if(!ready||answered)return;answered=true;let q=order[index];logs.push({version:DATA.version,session,subject,started,answered_at:new Date().toISOString(),trial:index+1,block:Math.floor(index/12)+1,template:q.id,level:q.level,first_ms:q.first_ms,second_ms:q.second_ms,response:value,answer:q.answer,correct:Number(value===q.answer),play_attempts:attempts,interruptions});$('a1').disabled=$('a2').disabled=true;$('result').textContent=value===q.answer?'回答正确。':`本题正确答案是第${q.answer}段。`;$('next').hidden=false;$('next').textContent=index===11?'进入休息':index===23?'完成本次':'下一题';store()}
$('a1').onclick=()=>answer(1);$('a2').onclick=()=>answer(2);
$('next').onclick=()=>{index++;store();if(index===24){show('done');$('summary').textContent=`完成24题，答对${logs.filter(x=>x.correct).length}题。正确率是本次练习记录，不是临床诊断结果。`}else if(index===12){show('break')}else draw()};$('continue').onclick=draw;
function download(){if(!logs.length){$('storage').textContent='尚无已作答记录。';return}let keys=Object.keys(logs[0]);function cell(v){let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}let csv='\ufeff'+keys.join(',')+'\r\n'+logs.map(r=>keys.map(k=>cell(r[k])).join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=session+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}$('export').onclick=download;$('download').onclick=download;
window.addEventListener('beforeunload',e=>{if(logs.length&&logs.length<24){e.preventDefault();e.returnValue=''}});
